// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function testFuzz_property(uint256 amount, address receiver) public {
        // Admissible domain: a nonzero, sendable amount and a receiver the
        // fuzzer picked (an EOA accepts the transfer, so no helper needed).
        vm.assume(receiver != address(c));
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, 1e30);

        // Fund the contract with the amount to send PLUS some leftover funds.
        vm.deal(address(c), amount);

        uint256 beforeBalance = address(c).balance;

        // The deployer (this test contract) is the owner.
        vm.prank(address(this));
        try c.sendTo(receiver, amount) {
            // Rule: a successful sendTo to a funded contract must transfer
            // exactly `amount`, leaving beforeBalance - amount in the contract.
            assertTrue(address(c).balance == beforeBalance - amount);
        } catch {
            // With sufficient funding the reference never reverts.
            assertTrue(false);
        }
    }
}
